const items = $input.all();

return items.map(item => {
  const data = item.json;
  let name = 'Unknown Employee';
  let email = 'user@example.com';
  let source = 'unknown';

  // 1. Detect Webhook / Web Form Trigger
  if (data.body || data.query) {
    source = 'web';
    // Web forms usually send data in the body
    const payload = (data.body && Object.keys(data.body).length > 0) ? data.body : (data.query || {});
    name = payload.name || name;
    email = payload.email || email;
  }
  // 2. Detect Email IMAP Trigger
  else if (data.from || (data.headers && data.headers.from)) {
    source = 'email';
    const fromVal = data.from?.value?.[0] || data.from || data.headers?.from;

    // Handle standard IMAP object format: { address: "user@example.com", name: "User" }
    if (fromVal && typeof fromVal === 'object') {
      email = fromVal.address || fromVal.email || email;
      name = fromVal.name || 'Email User'; // Set optional name for email
    } 
    // Handle raw string format: "John Doe <user@example.com>"
    else if (typeof fromVal === 'string') {
      const emailMatch = fromVal.match(/<([^>]+)>/);
      email = emailMatch ? emailMatch[1].trim() : fromVal.trim();
      name = fromVal.split('<')[0].trim() || 'Email User';
    }
  }

  return {
    json: {
      ...data,
      EmployeeName: name,
      EmployeeEmail: email,
      Source: source
    },
    // CRITICAL: Pass the binary file stream through to Gemini
    binary: item.binary || {}
  };
});

const items = $input.all();
const outputItems = [];

// Safely grab the normalized info from the first node
const sourceInfo = $('Capture Employee Info').first().json || {};

for (const item of items) {
  // Read raw text response across all possible Gemini response keys
  let rawText = item.json.content?.parts?.[0]?.text || item.json.text || item.json.response || item.json;

  if (typeof rawText === 'string') {
    // Strip markdown formatting if present
    rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
    try {
      rawText = JSON.parse(rawText);
    } catch (e) {
      console.error("Failed to parse JSON string:", e);
      continue; // Skip invalid parsing iterations
    }
  }

  // Extract claims array or wrap single objects
  const claims = rawText.claims || (Array.isArray(rawText) ? rawText : [rawText]);

  // Push each claim as an individual n8n item
  for (const claim of claims) {
    if (claim && typeof claim === 'object') {
      outputItems.push({
        json: {
          ...claim,
          Employee: sourceInfo.EmployeeName || 'Unknown Name',
          EmployeeEmail: sourceInfo.EmployeeEmail || 'Unknown Email',
          sourceFileName: item.json.fileName || 'Receipt_Document'
        }
      });
    }
  }
}

return outputItems;

// Retrieve parsed receipts, policy rules, and historical ledger entries
const receipts = $('Parse Extracted Data').all().map(i => i.json);
const policyRules = $('Get Policy Rules').all().map(i => i.json);

let historyData = [];
try {
  historyData = $('Get Employee history').all().map(i => i.json);
} catch (e) {
  console.log("Get Employee history node not found or empty.");
}

// Helper: Extract clean email from string formats
function extractCleanEmail(rawEmail) {
  if (!rawEmail) return '';
  const match = String(rawEmail).match(/<([^>]+)>/);
  return (match ? match[1] : rawEmail).trim().toLowerCase();
}

// Helper: Safely parse nested Extracted Data string
function getNestedData(obj) {
  const raw = obj['Extracted Data'] || obj.ExtractedData || obj.extractedData;
  if (typeof raw === 'string' && raw.trim().startsWith('{')) {
    try { return JSON.parse(raw); } catch (e) {}
  }
  return typeof raw === 'object' && raw !== null ? raw : {};
}

return receipts.map((receipt) => {
  let claim = { ...receipt };
  const nested = getNestedData(claim);

  // Core incoming properties with nested fallbacks
  const currentClaimID = String(claim.ClaimID || claim.claimId || nested.claimId || nested.ClaimID || '').trim();
  const currentAmount = Number(claim.Amount || claim.amount || nested.amount || 0);
  const category = String(claim.Category || claim.category || nested.category || 'Other').trim().toLowerCase();
  const currentVendor = String(claim.Vendor || claim.vendor || nested.vendor || '').trim().toLowerCase();

  const rawEmail = claim.EmployeeEmail || claim.email || nested.employeeEmail || nested.EmployeeEmail;
  const rawName = claim.Employee || claim.EmployeeName || nested.employeeName || nested.Employee;

  const currentEmail = extractCleanEmail(rawEmail);
  const currentName = String(rawName || '').trim().toLowerCase();

  // --- Filter Historical Data (Excluding Current Row/Claim) ---
  const priorHistory = historyData.filter(h => {
    const hNested = getNestedData(h);
    const hClaimID = String(h.ClaimID || h.claimId || hNested.claimId || hNested.ClaimID || '').trim();

    // Ignore current claim record if it's already written to Google Sheets
    if (currentClaimID && hClaimID && currentClaimID === hClaimID) {
      return false;
    }
    return true;
  });

  // Filter history belonging specifically to this employee
  const employeeHistory = priorHistory.filter(h => {
    const hNested = getNestedData(h);
    const sheetEmail = extractCleanEmail(h.EmployeeEmail || h['Employee Email'] || h.email || hNested.employeeEmail);
    const sheetName = String(h.Employee || h['Employee Name'] || hNested.employeeName || '').trim().toLowerCase();

    if (sheetEmail && currentEmail && sheetEmail === currentEmail) return true;
    if (sheetName && currentName && (sheetName.includes(currentName) || currentName.includes(sheetName))) return true;

    return false;
  });

  // Filter employee history for the same category
  const categoryHistory = employeeHistory.filter(h => {
    const hNested = getNestedData(h);
    const sheetCategory = String(h.Category || h.category || hNested.category || '').trim().toLowerCase();
    return sheetCategory === category;
  });

  // --- Assign Employee Metrics ---
  claim.EmployeeHistoryCount = employeeHistory.length;

  if (categoryHistory.length > 0) {
    const totalSpent = categoryHistory.reduce((sum, h) => {
      const hNested = getNestedData(h);
      const rawAmt = String(h.Amount || h.amount || hNested.amount || '0').replace(/[^0-9.-]+/g, '');
      return sum + (parseFloat(rawAmt) || 0);
    }, 0);

    claim.EmployeeAvgForCategory = Number((totalSpent / categoryHistory.length).toFixed(2));
  } else {
    claim.EmployeeAvgForCategory = currentAmount;
  }

  // --- Calculate IsNewVendor ---
  if (!currentVendor) {
    claim.IsNewVendor = false;
  } else {
    // Look across prior history to see if vendor existed before this claim
    const vendorExists = priorHistory.some(h => {
      const hNested = getNestedData(h);
      const sheetVendor = String(h.Vendor || h.vendor || hNested.vendor || '').trim().toLowerCase();
      return sheetVendor === currentVendor;
    });

    claim.IsNewVendor = !vendorExists;
  }

  // --- Policy Check Logic ---
  const isDuplicate = Boolean(claim.IsDuplicate);
  const rule = policyRules.find(r => String(r.Category || '').trim().toLowerCase() === category);
  const maxAuto = rule ? Number(rule['Max Amount']) : 500;

  if (!isDuplicate && currentAmount > 0 && currentAmount <= maxAuto) {
    claim.autoApprove = true;
    claim.RiskFlag = 'Low Risk';
    claim['Policy Check Result'] = `Auto-Approved (Under ₹${maxAuto} threshold)`;
  } else {
    claim.autoApprove = false;
    claim.RiskFlag = isDuplicate ? 'High - DUPLICATE SUSPECTED' : 'Medium - REQUIRES SIGN-OFF';
    claim['Policy Check Result'] = isDuplicate ? 'Requires Sign-off (Duplicate Found)' : 'Requires Manager Sign-off';
  }

  return { json: claim };
});

