const items = $input.all();
const outputItems = [];

const ALLOWED_MIME_PREFIXES = ['image/'];
const ALLOWED_MIME_EXACT = ['application/pdf'];

function isSupportedFile(binaryData) {
  const mime = (binaryData.mimeType || '').toLowerCase();
  if (ALLOWED_MIME_EXACT.includes(mime)) return true;
  return ALLOWED_MIME_PREFIXES.some(prefix => mime.startsWith(prefix));
}

for (const item of items) {
  if (item.binary && Object.keys(item.binary).length > 0) {
    // Loop through all attachments in the single email/webhook payload (bulk support)
    for (const [key, binaryData] of Object.entries(item.binary)) {
      if (!isSupportedFile(binaryData)) continue; // skip signatures, ICS files, etc.

      outputItems.push({
        json: {
          ...item.json,
          processedAttachmentKey: key,
          fileName: binaryData.fileName || binaryData.filename || 'receipt_file',
          fileMimeType: binaryData.mimeType || 'unknown'
        },
        // Standardizes binary to 'data' for the Gemini node
        binary: {
          data: binaryData
        }
      });
    }
  } else {
    outputItems.push(item);
  }
}

return outputItems;

