const items = $input.all();
const outputItems = [];

for (const item of items) {
  if (item.binary && Object.keys(item.binary).length > 0) {
    for (const [key, binaryData] of Object.entries(item.binary)) {
      outputItems.push({
        json: {
          ...item.json,
          sourceFileKey: key,
          fileName: binaryData.fileName || binaryData.filename || `file_${key}`,
          mimeType: binaryData.mimeType || 'application/octet-stream',
          fileExtension: binaryData.fileExtension || ''
        },
        binary: {
          // Normalizes all binary streams to a consistent 'data' key for Gemini
          data: binaryData
        }
      });
    }
  } else {
    outputItems.push(item);
  }
}

return outputItems;

const query = $('Webhook: Expense Decision').first().json.query || {};
const action = (query.action || '').toString().toLowerCase().trim();
const claimId = query.claimId || query.claimID || query.ClaimID || '';

return {
  json: {
    ...$input.item.json,
    action: action,
    claimId: claimId,
    ClaimID: claimId,
    isApproved: action === 'approve'
  }
};

const current = $input.item.json || {};
const amount = Number(current.Amount) || 0;
const isAuto = Boolean(current.autoApprove);
const isDup = Boolean(current.IsDuplicate);

// Determine risk status safely
const riskValue = isDup 
  ? 'High - DUPLICATE SUSPECTED' 
  : (current.RiskFlag || (isAuto ? 'Low' : 'Medium - REQUIRES SIGN-OFF'));

// Determine policy result safely
const policyResult = current['Policy Check Result'] 
  || current.PolicyCheckRes 
  || (isAuto ? 'Auto-Approved' : 'Requires Manager Sign-off');

return {
  json: {
    // Basic Info
    Vendor: current.Vendor || 'Unknown Vendor',
    Amount: amount,
    Category: current.Category || 'Other',
    Date: current.Date || new Date().toISOString().split('T')[0],
    ClaimID: current.ClaimID || 'CLM-' + Math.random().toString(36).substring(2, 8).toUpperCase(),
    Employee: current.Employee || 'Mohd Maaz Khan',
    EmployeeEmail: current.EmployeeEmail || 'user@example.com',
    EmployeeChatId: current.EmployeeChatId || 7247804267,

    // Workflow State
    autoApprove: isAuto,
    Status: isAuto ? 'Auto-Approved' : 'Pending Approval',
    ApprovedBy: isAuto ? 'AI Agent' : '',
    approvalLevelRequired: isAuto ? 'Auto' : 'Manager',
    Timestamp: new Date().toISOString(),

    // Risk, Metrics & Policy
    IsDuplicate: isDup,
    IsNewVendor: Boolean(current.IsNewVendor),
    EmployeeHistoryCount: current.EmployeeHistoryCount || 0,
    EmployeeAvgForCategory: current.EmployeeAvgForCategory || 0,

    // Both key formats to prevent missing fields in Google Sheets
    RiskFlag: riskValue,
    'Risk Flag': riskValue,
    PolicyCheckRes: policyResult,
    'Policy Check Result': policyResult,

    // Full JSON dump for "Extracted Data" column
    ExtractedData: JSON.stringify(current)
  }
};

// Pull array items directly from Parse Extracted Data / Check Policy and Risk
const evaluatedItems = $('Check Policy and Risk').all().map(i => i.json);
const ledgerItems = $('Get Ledger History').all().map(i => i.json);

return evaluatedItems.map((current, index) => {
  const currentAmount = Number(current.Amount) || 0;
  const currentVendor = String(current.Vendor || '').toLowerCase().trim();

  // Check ledger for duplicates
  const isDuplicate = ledgerItems.length > 0 && ledgerItems.some(row => {
    const rowVendor = String(row.Vendor || row.vendor || '').toLowerCase().trim();
    const rowAmount = Number(row.Amount || row.amount) || 0;
    return rowVendor === currentVendor && rowAmount === currentAmount && currentAmount > 0;
  });

  const finalAutoApprove = !isDuplicate && Boolean(current.autoApprove);

  return {
    json: {
      Vendor: current.Vendor || 'Unknown Vendor',
      Amount: currentAmount,
      Category: current.Category || 'Meals',
      Date: current.Date || new Date().toISOString().split('T')[0],
      ClaimID: current.ClaimID || Math.random().toString(36).substring(2, 9),
      Employee: current.Employee || 'Mohd Maaz Khan',
      EmployeeEmail: current.EmployeeEmail || 'user@example.com',
      EmployeeChatId: current.EmployeeChatId || 7247804267,
      IsDuplicate: isDuplicate,
      autoApprove: finalAutoApprove,
      RiskFlag: isDuplicate 
        ? 'High - DUPLICATE SUSPECTED' 
        : (current.RiskFlag || 'Low Risk'),
      'Policy Check Result': isDuplicate 
        ? 'Requires Sign-off (Duplicate Found)' 
        : (current['Policy Check Result'] || 'Requires Manager Sign-off')
    }
  };
});

